def compute(vars):
    consolidated = vars["v1"]
    affiliates = vars["v2"]
    total = consolidated + affiliates
    return {
        "value": total,
        "trace": {
            "consolidated_subsidiaries": consolidated,
            "non_consolidated_affiliates": affiliates,
            "total": total,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None,
            },
        },
    }
